euk onmogelijk. Wanneer hun vijandige omgang een andere wending krijgt, komen ook de redenen voor hun onderlinge wantrouwen terug. In dit deel van de Knockemout-serie botsen hun verschillende levens en verlangens. Ze moeten ontdekken of de band die hen al zo lang verbindt ook ruimte laat voor verandering.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1765666/things-we-left-behind.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1765666/things-we-left-behind.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"3d75d0c2c86653b15fdf820a002899b57f3512e1dad8a1b3c669b67463fcedc4"}]}},{"relation":"editions","ref":"edition:9789021476063","key":{"id":976200128},"before":null,"after":{"work_id":924100683,"title":"Twisted love","isbn_13":"9789021476063","isbn_10":null,"language":"nld","publisher":"Singel Uitgeverijen","open_library_edition_id":null,"id":976200128}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021476063","key":{"edition_id":"@edition:9789021476063"},"before":null,"after":{"edition_id":"@edition:9789021476063","work_id":924100683,"bound_author_id":924300405,"bound_title":"Twisted love","bound_language":"nld","bound_isbn13":"9789021476063","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000537567_Twisted_love_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1783383/twisted-love.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1783383/twisted-love.html","checkedAt":"2026-11-01","sha256":"2e932f30ded4aec5ca97f2a18e3d189fb0f9b0a46eecd8bcd9c31406e95a55b7","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie_fcache/0000537567_Twisted_love_0_0.jpg","checkedAt":"2026-11-01T10:57:11.614Z","sha256":"a0f1d43f3355bdba95dea8f006b6368d903d8abeefacb3298cf353901113fb91","bytes":305353,"fact":"Same-edition source association and title/author artwork visually reviewed; not only HTTP200"}]}},{"relation":"catalog_work_descriptions","ref":"description:683","key":{"work_id":924100683,"language":"nl"},"before":null,"after":{"work_id":924100683,"language":"nl","bound_author_id":924300405,"text":"Alex Volkov houdt zijn leven streng onder controle en laat weinig mensen dichtbij komen. Wanneer zijn vriend naar het buitenland vertrekt, vraagt die hem op zijn zus Ava te letten. Haar open manier van kijken botst met Alex'' gesloten houding. Terwijl hun band verandert, blijven gebeurtenissen uit hun jeugd invloed uitoefenen op wat zij van elkaar durven verwachten. De roman volgt een toenadering die oude geheimen niet vanzelf laat verdwijnen.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1783383/twisted-love.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1783383/twisted-love.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"2e932f30ded4aec5ca97f2a18e3d189fb0f9b0a46eecd8bcd9c31406e95a55b7"}]}},{"relation":"editions","ref":"edition:9789021476087","key":{"id":976200129},"before":null,"after":{"work_id":924100688,"title":"Twisted hate","isbn_13":"9789021476087","isbn_10":null,"language":"nld","publisher":"Singel Uitgeverijen","open_library_edition_id":null,"id":976200129}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021476087","key":{"e