re":null,"after":{"work_id":924100698,"language":"nl","bound_author_id":924300397,"text":"Anastasia en Christian proberen hun gezamenlijke toekomst vorm te geven, maar hun huwelijk neemt de spanningen tussen hen niet weg. Anastasias behoefte aan zelfstandigheid botst met Christians behoefte aan controle en veiligheid. Ook gebeurtenissen uit het verleden blijven hen achtervolgen. Het laatste deel van de trilogie volgt hoe hun verhouding onder druk komt te staan wanneer persoonlijk vertrouwen en bedreigingen van buiten hun zorgvuldig opgebouwde leven raken.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/77053/vijftig-tinten-vrij.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/77053/vijftig-tinten-vrij.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"1bd0db738139ec9a955765bc55de79a92782aaa0be699c125f5bf100ea2089d6"}]}},{"relation":"editions","ref":"edition:9789021485836","key":{"id":976200131},"before":null,"after":{"work_id":924100699,"title":"King of pride","isbn_13":"9789021485836","isbn_10":null,"language":"nld","publisher":"Singel Uitgeverijen","open_library_edition_id":null,"id":976200131}},{"relation":"catalog_edition_metadata","ref":"metadata:9789021485836","key":{"edition_id":"@edition:9789021485836"},"before":null,"after":{"edition_id":"@edition:9789021485836","work_id":924100699,"bound_author_id":924300405,"bound_title":"King of pride","bound_language":"nld","bound_isbn13":"9789021485836","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000632302_King_of_pride_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1804575/king-of-pride.html","review_status":"approved","reviewed_at":"2026-11-01