g in Nederland blijft Niels worstelen met wat hij heeft gezien. Een nieuwe moord in hetzelfde gebied roept vervolgens vragen op over de eerdere gebeurtenissen en wat hij zich daarvan herinnert.","source_type":"official_catalog","source_name":"Bureau ISBN; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/46044/bella-italia.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/46044/bella-italia.html","checkedAt":"2026-11-01","fact":"Source content actually read; original Dutch synopsis, identity reviewed separately","sha256":"e629507f42975e52be08b33bde5559dbc065195b518f3ea01c37b4e33ceda7ca"}]}},{"relation":"editions","ref":"edition:9789400517776","key":{"id":976200136},"before":null,"after":{"work_id":91021010,"title":"Bon Bini Beach","isbn_13":"9789400517776","isbn_10":null,"language":"nld","publisher":"Bruna Uitgevers B.V., A.W.","open_library_edition_id":null,"id":976200136}},{"relation":"catalog_edition_metadata","ref":"metadata:9789400517776","key":{"edition_id":"@edition:9789400517776"},"before":null,"after":{"edition_id":"@edition:9789400517776","work_id":91021010,"bound_author_id":91021002,"bound_title":"Bon Bini Beach","bound_language":"nld","bound_isbn13":"9789400517776","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000633438_Bon_Bini_Beach_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1545951/bon-bini-beach.html","review_status":"approved","reviewed_at":"2026-11-01T11:04:00Z","review_batch":"nl005-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/1545951/bon-bini-beach.html","checkedAt":"2026-11-01","sha256":"75399d977fc3cdfa9d673e483e80c6128524892d8be1633428fcd764ecaf0662","fact":"Exact title/author/ISBN, physical format and language source reviewed; independent contradictions recorded"},{"url":"https://metadata.isbn.nl/ie